window.ScripturaLexicons.BDAG_PART_0361 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0361-01\" data-source=\"BDAG\" data-search=\"τοῦτο pronome demonstrativo remissão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τοῦτο</td><td>pronome demonstrativo</td><td>remissão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0361-02\" data-source=\"BDAG\" data-search=\"τράγος, ου, ὁ substantivo masculino bode BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τράγος, ου, ὁ</td><td>substantivo masculino</td><td>bode</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0361-03\" data-source=\"BDAG\" data-search=\"Τράλλεις, εων, αἱ nome próprio feminino plural Trales BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Τράλλεις, εων, αἱ</td><td>nome próprio feminino plural</td><td>Trales</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0361-04\" data-source=\"BDAG\" data-search=\"Τραλλιανός, οῦ, ὁ substantivo masculino traliano BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Τραλλιανός, οῦ, ὁ</td><td>substantivo masculino</td><td>traliano</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0361-05\" data-source=\"BDAG\" data-search=\"τράπεζα, ης, ἡ substantivo feminino mesa; banco; refeição BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τράπεζα, ης, ἡ</td><td>substantivo feminino</td><td>mesa; banco; refeição</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0361-06\" data-source=\"BDAG\" data-search=\"τραπεζίτης, ου, ὁ substantivo masculino cambista; banqueiro BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τραπεζίτης, ου, ὁ</td><td>substantivo masculino</td><td>cambista; banqueiro</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0361-07\" data-source=\"BDAG\" data-search=\"τραυλισμός , οῦ, ὁ substantivo masculino balbucio; ruído irregular BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τραυλισμός , οῦ, ὁ</td><td>substantivo masculino</td><td>balbucio; ruído irregular</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0361-08\" data-source=\"BDAG\" data-search=\"τραῦμα, ατος, τό substantivo neutro ferida BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τραῦμα, ατος, τό</td><td>substantivo neutro</td><td>ferida</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0361-09\" data-source=\"BDAG\" data-search=\"τραυματίζω verbo ferir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τραυματίζω</td><td>verbo</td><td>ferir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0361-10\" data-source=\"BDAG\" data-search=\"τραχηλίζω verbo desnudar; revelar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τραχηλίζω</td><td>verbo</td><td>desnudar; revelar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0361-11\" data-source=\"BDAG\" data-search=\"τραχηλοκοπέω verbo decapitar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τραχηλοκοπέω</td><td>verbo</td><td>decapitar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0361-12\" data-source=\"BDAG\" data-search=\"τράχηλος, ου, ὁ substantivo masculino pescoço; garganta BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τράχηλος, ου, ὁ</td><td>substantivo masculino</td><td>pescoço; garganta</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0361-13\" data-source=\"BDAG\" data-search=\"τραχύς, εῖα, ύ adjetivo áspero; irregular BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τραχύς, εῖα, ύ</td><td>adjetivo</td><td>áspero; irregular</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0361-14\" data-source=\"BDAG\" data-search=\"Τραχωνῖτις, ιδος nome próprio feminino Traconítide BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Τραχωνῖτις, ιδος</td><td>nome próprio feminino</td><td>Traconítide</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0361-15\" data-source=\"BDAG\" data-search=\"τρεῖς, τρία numeral cardinal três BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τρεῖς, τρία</td><td>numeral cardinal</td><td>três</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0361-16\" data-source=\"BDAG\" data-search=\"Τρεῖς Ταβέρναι nome próprio plural remissão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Τρεῖς Ταβέρναι</td><td>nome próprio plural</td><td>remissão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0361-17\" data-source=\"BDAG\" data-search=\"τρέμω verbo tremer; temer BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τρέμω</td><td>verbo</td><td>tremer; temer</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0361-18\" data-source=\"BDAG\" data-search=\"τρέπω verbo voltar; dirigir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τρέπω</td><td>verbo</td><td>voltar; dirigir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0361-19\" data-source=\"BDAG\" data-search=\"τρέφω verbo alimentar; criar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τρέφω</td><td>verbo</td><td>alimentar; criar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0361-20\" data-source=\"BDAG\" data-search=\"τρέχω verbo correr; progredir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τρέχω</td><td>verbo</td><td>correr; progredir</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0361-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τοῦτο</h1><div class=\"entry-meta\"><span>pronome demonstrativo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τοῦτο</span> v. <span class=\"greek\">οὗτος</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0361-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τράγος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τράγος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (Hom.+; inscrições, papiros, LXX, Philo; Jos., Ant. 2, 35; Ar. 12, 7; Just.) bode, mencionado com outros como animal sacrificial <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.12\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:12f</a>, 19; 10:4; B 2:5 (Is 1:11). Empregado especialmente no Dia da Expiação 7:4 (dito profético de origem desconhecida), 6, 8, 10.—B. 165. DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0361-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Τράλλεις, εων, αἱ</h1><div class=\"entry-meta\"><span>nome próprio feminino plural</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Τράλλεις</span>, <span class=\"greek\">εων</span>, <span class=\"greek\">αἱ</span> (X., An. 1, 4, 8 al.; inscrições. Ocorre principalmente na forma pl. [X.; Diod S 14, 36, 3; Jos., Ant. 14, 245; OGI 441, 162], embora o sing. <span class=\"greek\">Τράλλις</span>, <span class=\"greek\">ιος</span> [epigrama em Agathias Hist. p. 102, 15; Stephan. Byz. s.v.; SibOr 3, 459; 5, 289] não seja impossível) Trales, cidade da Cária (sudoeste da Ásia Menor), ao norte do rio Meandro, ITr ins.—KHumann/WDorpfeld, MAI 18, 1893, 395ff; JWeiss, RE X 547; VSchultze, Altchristliche Städte und Landschaften II/2, 1926; GBean, Turkey beyond the Maeander ’71, 208–11; Pauly-W. VI 2093–128; Kl. Pauly V 922; judeus residentes, Schürer III 24, 167; PECS 931.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0361-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Τραλλιανός, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Τραλλιανός</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> (Strabo 14, 1, 42; Appian, Mithr. 23; Polyaenus 7, 41; Jos., Ant. 14, 242; inscrições [OGI 498, 3, SIG índice p. 156; IMagnMai índice p. 204b]; corretamente e predominantemente com <span class=\"greek\">λ</span> duplo) traliano, de Trales (v. <span class=\"greek\">Τράλλεις</span>), a respeito do <span class=\"greek\">ἀρχιερεύς</span> Filipe, sob o qual Policarpo sofreu o martírio MPol 21. V. também o título de ITr (Apolônio de Tiana escreveu uma carta <span class=\"greek\">Τραλλιανοῖς</span> [n.º 69]: Philostrat. I p. 364).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0361-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τράπεζα, ης, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τράπεζα</span>, <span class=\"greek\">ης</span>, <span class=\"greek\">ἡ</span> (Hom.+; inscrições, papiros, LXX, TestSol, TestAbr, TestJob, Test12Patr, JosAs; SibOr 5, 470; EpArist; Philo; Joseph.; Ath., R. 4 p. 52, 21; empréstimo na literatura rabínica)</p><p class=\"entry-text\"><span class=\"sense-number\">①</span> estrutura ou superfície sobre a qual podem ser colocados alimentos ou outras coisas, mesa</p><p class=\"entry-text\"><span class=\"sense-number\">ⓐ</span> a respeito de um objeto cultual: a mesa dos pães da proposição (cf. 1 Macc 1:22 <span class=\"greek\">τρ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">προθέσεως</span>; Ex 25:23–30; Jos., Bell. 5, 217) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.2\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:2</a>. A respeito da <span class=\"greek\">τράπεζα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> no tabernáculo, sobre a qual Moisés colocou as doze varas 1 Cl 43:2.</p><p class=\"entry-text\"><span class=\"sense-number\">ⓑ</span> especificamente a mesa sobre a qual se dispõe uma refeição (Hom. et al.; Jos., Ant. 8, 239) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:27</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:28</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 16:21</a>; 22:21. A respeito da mesa celestial à qual os companheiros do Messias comerão no fim dos tempos v. 30 (v. JJeremias, Zöllner u. Sünder, ZNW 30, ’31, 293–300). Também em <span class=\"greek\">γενηθήτω</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">τράπεζα</span> <span class=\"greek\">αὐτῶν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">παγίδα</span> é provável (cf. Jos., Ant. 6, 363) que se tenha em vista esse tipo de mesa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 11:9</a> (Ps 68:23).—O contraste entre <span class=\"greek\">τράπεζα</span> <span class=\"greek\">κυρίου</span> e <span class=\"greek\">τρ</span>. <span class=\"greek\">δαιμονίων</span> 1 Cor 10:21 explica-se pelo costume de tomar uma refeição cultual no templo das divindades adoradas pelos politeístas (POxy 110 <span class=\"greek\">ἐρωτᾷ</span> <span class=\"greek\">σε</span> <span class=\"greek\">Χαιρήμων</span> <span class=\"greek\">δειπνῆσαι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">κλείνην</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span> <span class=\"greek\">Σαράπιδος</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">Σαραπείῳ</span> <span class=\"greek\">αὔριον</span>, <span class=\"greek\">ἥτις</span> <span class=\"greek\">ἐστὶν</span> <span class=\"greek\">ιε</span>´, <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">ὥρας</span> <span class=\"greek\">θ</span>´ ‘Querêmon convida-te a jantar à mesa de Sarápis no Sarapeu amanhã, dia 15, à hora nona’; 523; POslo 157 [todos os três II d.C.]; Jos., Ant. 18, 65. <span class=\"greek\">τράπεζα</span> a respeito da mesa de uma divindade encontra-se em contextos tais e semelhantes Diod S 5, 46, 7 <span class=\"greek\">τρ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>; SIG 1106, 99 <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">τράπεζαν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>; 1022, 2; 1038, 11; 1042, 20; LBW 395, 17 <span class=\"greek\">Σαράπιδι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">Ἴσιδι</span> <span class=\"greek\">τράπεζαν</span>; POxy 1755. Cf. Sb 8828, 4 [180–82 d.C.] <span class=\"greek\">ἐν</span> <span class=\"greek\">ὀνίροις</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">συμπόσιον</span> <span class=\"greek\">ποιῆσαι</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span> <span class=\"greek\">Σεράπιδος</span>=celebrar a refeição com o senhor Sarápis em sonhos; v. também New Docs 1, 5–9; 2, 37; 3, 69.—Ltzm., Hdb. excurso sobre 1 Cor 10:21; HMischkowski, D. hl. Tische im Götterkultus d. Griech. u. Römer, diss. Königsberg 1917).</p><p class=\"entry-text\"><span class=\"sense-number\">ⓒ</span> a mesa sobre a qual os cambistas expõem suas moedas (Pla., Ap. 17c; cf. PEleph 10, 2 [223/222 a.C.] os <span class=\"greek\">τραπεζῖται</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἱεροῖς</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 11:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">J 2:15</a>. Daí simplesmente banco (Lysias, Isocr., Demosth. et al.; EpArist; Jos., Ant. 12, 28; inscrições; PEleph 27, 23; POxy 98 al. nos papiros. O inglês ‘bank’ é o ‘banco’ do prestamista; v. OED s.v. bank sb.3) <span class=\"greek\">διδόναι</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἀργύριον</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τράπεζαν</span> depositar o dinheiro no banco para render juros <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 19:23</a>.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.6.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 6:2</a> pode conter um jogo de palavras humorístico, que combina a ideia do serviço à mesa com procedimentos contábeis: servir como contadores (sobre a terminologia bancária, v. Field, Notes 113, remetendo a Plut., Caesar 721 [28, 4]; 739 [67, 1], mas desconsiderando o serviço de refeições como referente. Além das observações de Field, note-se o provável jogo de palavras relativo a <span class=\"greek\">λόγος</span> [quanto à sua nuance comercial, v. <span class=\"greek\">λόγος</span> 2a sobre o mesmo versículo; v. também Goodsp., Probs. 126f, com referências a papiros]. Quanto às inscrições, v. RBogaert, Epigraphica III ’76 índice).—B. 352 (refeição); 483; 778 (banco).</p><p class=\"entry-text\"><span class=\"sense-number\">②</span> aquilo que está sobre uma mesa, refeição, alimento, extensão metonímica de 1 (Eur., Alc. 2; Hdt. 1, 162; Pla., Rep. 3, 404d; Lucian, Dial. Mort. 9, 2; Athen. 1, 25e) <span class=\"greek\">παραθεῖναι</span> <span class=\"greek\">τράπεζαν</span> pôr alimento diante de alguém (Thu. 1, 130; Chariton 1, 13, 2; Aelian, VH 2, 17; Jos., Ant. 6, 338.—Ps 22:5 <span class=\"greek\">ἑτοιμάζειν</span> <span class=\"greek\">τρ</span>.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.34\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:34</a>; <span class=\"greek\">τράπ</span>. <span class=\"greek\">κοινήν</span> (<span class=\"greek\">κοινός</span> 1a) Dg 5:7. <span class=\"greek\">ὁρίζειν</span> <span class=\"greek\">τράπεζαν</span> encomendar uma refeição D 11:9. <span class=\"greek\">διακονεῖν</span> <span class=\"greek\">τραπέζαις</span> servir às mesas, servir refeições <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.6.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 6:2</a> (assim ELohmeyer, JBL 56, ’37, 231; 250f, mas v. 1c acima).—V. GRichter, The Furniture of the Greeks, Etruscans, and Romans ’66; Kl. Pauly III 1224f; BHHW III 1991–93.—DELG. M-M. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0361-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τραπεζίτης, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τραπεζίτης</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (também -<span class=\"greek\">είτης</span>; de <span class=\"greek\">τράπεζα</span>; Lysias, Demosth.; inscrições, papiros; EpArist 26=Jos., Ant. 12, 32; empréstimo na literatura rabínica) cambista, banqueiro <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:27</a>. <span class=\"greek\">δόκιμος</span> <span class=\"greek\">τραπεζίτης</span> cambista experiente, que não aceita dinheiro falso; em linguagem figurada (sobre o assunto, v. Philo, Spec. Leg. 4, 77) a respeito dos cristãos <span class=\"greek\">γίνεσθε</span> <span class=\"greek\">δόκιμοι</span> <span class=\"greek\">τραπεζῖται</span> Agr 11a, cf. b (Cebes 31, 3 <span class=\"greek\">μηδὲ</span> <span class=\"greek\">γίνεσθαι</span> <span class=\"greek\">ὁμοίους</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">κακοῖς</span> <span class=\"greek\">τραπεζίταις</span>). AResch, Agrapha2 1906, 112–28; HVogels, BZ 8, 1910, 390; HSchoeps, Theol. u. Gesch. des Judenchristentums ’49, 151–55; Unknown Sayings 89–93.—Cf. PEleph s.v. <span class=\"greek\">τράπεζα</span> 1c. Quanto às inscrições, v. RBogaert, Epigraphica III ’76 índice.—New Docs 1, 138 n.º 87. DELG s.v. <span class=\"greek\">τράπεζα</span>. M-M. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0361-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τραυλισμός , οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τραυλισμός</span> , <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> (de <span class=\"greek\">τραυλός</span> [por intermédio de <span class=\"greek\">τραυλίζω</span>] ‘pronunciar incorretamente as letras, balbuciar’; Hippocr.; [leitura incerta em Erotian 126, 4]; Plut., Mor. 53c a respeito da dificuldade de dicção de Aristóteles) lit. ‘balbucio, gagueira’, em sentido figurado, ruído irregular produzido por veículos de madeira em estradas desiguais <span class=\"greek\">ἤκουεν</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἁμαξῶν</span> <span class=\"greek\">τραυλισμόν</span> (Paulo) ouvia o estrépito rangente dos carros AcPl Ha 2, 3.—DELG s.v. <span class=\"greek\">τραυλός</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0361-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τραῦμα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τραῦμα</span>, <span class=\"greek\">ατος</span>, <span class=\"greek\">τό</span> (de <span class=\"greek\">τιτρώσκω</span>, cf. o jônico/dórico <span class=\"greek\">τρῶμα</span>; Aeschyl., Hdt. et al.; inscrições, papiros, LXX; Jos., Bell. 1, 197, Ant. 4, 92al.; Ath., R. 22 p. 75, 17) ferida <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.34\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:34</a>; IPol 2:1.—B. 304. Schmidt, Syn. III 297–302. DELG s.v. <span class=\"greek\">τιτρώσκω</span>. M-M. V. também <span class=\"greek\">ἕλκος</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0361-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τραυματίζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τραυματίζω</span> (<span class=\"greek\">τραῦμα</span>) 1 aor. <span class=\"greek\">ἐτραυμάτισα</span>, pass. <span class=\"greek\">ἐτραυματίσθην</span>; partic. perf. pass. <span class=\"greek\">τετραυματισμένος</span> (Aeschyl., Hdt. et al.; papiros, LXX; JosAs 27:3 cod. A 29, 8 [p. 85, 10 Bat.]; Jos., C. Ap. 2, 243) ferir <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 19:16</a>; 1 Cl 16:5; B 5:2 (os dois últimos Is 53:5).—DELG s.v. <span class=\"greek\">τιτρώσκω</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0361-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τραχηλίζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τραχηλίζω</span> (<span class=\"greek\">τράχηλος</span>) partic. perf. pass. <span class=\"greek\">τετραχηλισμένος</span> (Theophr., Teles et al. em sentido diferente [torcer o pescoço etc.]; Philo, Cher. 78, Mos. 1, 297; Jos., Bell. 4, 375; PPetr II, 15 [1]a, 2); em sua única ocorrência em nossa literatura <span class=\"greek\">πάντα</span> <span class=\"greek\">γυμνὰ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τετραχηλισμένα</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ὀφθαλμοῖς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.4.13\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 4:13</a> certamente deve significar desnudar: tudo está aberto e desnudado aos olhos (Hesíquio explica <span class=\"greek\">τετραχηλισμένα</span> por <span class=\"greek\">πεφανερωμένα</span>, e já em Enômao, em Eus., PE 5, 29, 5, temos <span class=\"greek\">μισθοῦ</span> <span class=\"greek\">τραχηλίζειν</span>=‘revelar’ ou ‘abrir mediante pagamento’).—WWood, Exp. 9th ser., 3, 1925, 444–55; CSpicq, RB 58, ’51, 484 n. 2; HMontefiore, The Epistle to the Hebrews ’64, 89 (‘tudo está nu e prostrado diante de … ele’).—DELG s.v. <span class=\"greek\">τράχηλος</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0361-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τραχηλοκοπέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τραχηλοκοπέω</span> (<span class=\"greek\">τράχηλος</span>, <span class=\"greek\">κόπτω</span>) 1 subj. aor. <span class=\"greek\">τραχηλοκοπήσῃς</span>, aor. pass. <span class=\"greek\">ἐτραχηλοκοπήθην</span>; perf. <span class=\"greek\">τετραχηλοκόπημαι</span> decapitar <span class=\"greek\">Καῖσαρ</span> <span class=\"greek\">ἐκέλευσεν</span> … <span class=\"greek\">Παῦλον</span> <span class=\"greek\">τραχηλο</span>[<span class=\"greek\">κοπηθῆναι</span>] AcPl Ha 9, 16; v. também 9, 25 e 27; 10, 10–11; 11, 1.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0361-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τράχηλος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τράχηλος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (Eur., Hdt.+; inscrições, papiros, LXX; TestSol, TestAbr; TestNapht 2:8; JosAs, ParJer; Jos., Ant. 3, 170 al.; Ath. 20, 1) pescoço, garganta <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.42\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:42</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 17:2</a> (cf. Menand., Fgm. 224 Kö. <span class=\"greek\">περὶ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">τρ</span>. <span class=\"greek\">ἁλύσιον</span> <span class=\"greek\">διδόναι</span>). <span class=\"greek\">ἐπιπεσεῖν</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">τράχηλόν</span> <span class=\"greek\">τινος</span> lançar-se ao pescoço de alguém, abraçar alguém (<span class=\"greek\">ἐπιπίπτω</span> 1b) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.20\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 15:20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.37\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:37</a>. <span class=\"greek\">ἐκρέμασεν</span> <span class=\"greek\">ἁτὴν</span> (por <span class=\"greek\">αὑτὴν</span>) <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">τράχηλον</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">Ἅννα</span> Ana lançou-se ao pescoço dele GJs 4:4 (v. <span class=\"greek\">κρεμάννυμι</span> 1 e <span class=\"greek\">περιπλέκω</span>).—Em linguagem figurada: <span class=\"greek\">οἵτινες</span> <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ψυχῆς</span> <span class=\"greek\">μου</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ἑαυτῶν</span> <span class=\"greek\">τράχηλον</span> <span class=\"greek\">ὑπέθηκαν</span> que arriscaram o próprio pescoço por minha vida <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 16:4</a> (cf. Vita Philonidis ed. Crönert [SBBerlAk 1900, 951] <span class=\"greek\">ὑπὲρ</span>[?] <span class=\"greek\">τοῦ</span> <span class=\"greek\">μάλιστ</span>’ <span class=\"greek\">ἀγαπωμένου</span> <span class=\"greek\">παραβάλοι</span> <span class=\"greek\">ἂν</span> <span class=\"greek\">ἑτοίμως</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">τράχηλον</span>. Sobre isso, v. Dssm., LO 94f [LAE 117f]. Pôr em perigo o <span class=\"greek\">τράχηλος</span> Diog. L. 4, 11; v. Straub 47). Por outro lado, <span class=\"greek\">ὑποθεῖναι</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">τράχηλον</span> 1 Cl 63:1 curvar o pescoço em obediência (cf. Epict. 4, 1, 77.—Sir 51:26). Também <span class=\"greek\">κάμπτειν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">τράχ</span>. B 3:2 (Is 58:5). Oposto <span class=\"greek\">τὸν</span> <span class=\"greek\">τράχ</span>. <span class=\"greek\">σκληρύνειν</span> 9:5 (Dt 10:16; PsSol 8:29). <span class=\"greek\">ἐπιθεῖναι</span> <span class=\"greek\">ζυγὸν</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">τράχ</span>. <span class=\"greek\">τινος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:10</a> (cf. escólio sobre Appol. Rhod. 4, 1418 <span class=\"greek\">τὸ</span> <span class=\"greek\">βάρος</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">τραχήλου</span> <span class=\"greek\">ἀποβαλέσθαι</span>).—B. 232. DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0361-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τραχύς, εῖα, ύ</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τραχύς</span>, <span class=\"greek\">εῖα</span>, <span class=\"greek\">ύ</span> (provavelmente cognato de <span class=\"greek\">θράσσω</span> ‘perturbar, agitar’; Hom.+; inscrições, papiros, LXX, En, PsSol 8:17; EpArist, Philo; Jos., Bell. 4, 5, Ant. 7, 239 al.) áspero, irregular, a respeito de uma montanha (Herodian 6, 5, 5) Hs 9, 1, 7; 9, 22, 1. A respeito de pedras (Hom. et al.) 9, 6, 4; 9, 8, 6. <span class=\"greek\">τραχεῖς</span> <span class=\"greek\">τόποι</span> (escólio sobre Nicander, Ther. 143) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:29</a>. A respeito de uma estrada (Hyperid., Fgm. 70, 3 J. <span class=\"greek\">τραχεῖα</span> <span class=\"greek\">ὁδός</span>; Pla., Rep. 1, 328e <span class=\"greek\">ὁδὸς</span> <span class=\"greek\">τραχεῖα</span>; Cebes 15, 2; Jer 2:25; Bar 4:26; PsSol 8:17) Hm 6, 1, 3f. <span class=\"greek\">ἡ</span> <span class=\"greek\">τραχεῖα</span> (X., An. 4, 6, 12; Lucian, Rhet. Praec. 3; subentende-se <span class=\"greek\">ὁδός</span>) a estrada áspera, pl. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:5</a> (Is 40:4).—B. 1066. DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0361-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Τραχωνῖτις, ιδος</h1><div class=\"entry-meta\"><span>nome próprio feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Τραχωνῖτις</span>, <span class=\"greek\">ιδος</span> (Philo, Leg. ad Gai. 326; Joseph. índice s.v. <span class=\"greek\">Τράχων</span>) fem. de <span class=\"greek\">Τραχωνίτης</span>, como Joseph. denomina um habitante <span class=\"greek\">τοῦ</span> <span class=\"greek\">Τράχωνος</span>. O fem. é empregado absolutamente por Philo e Joseph. <span class=\"greek\">ἡ</span> <span class=\"greek\">Τραχωνῖτις</span>=(a) Traconítide. Trata-se do distrito ao sul de Damasco, também denominado <span class=\"greek\">ὁ</span> <span class=\"greek\">Τράχων</span> por Josefo. Na única passagem em que a palavra ocorre em nossa literatura, é empregada como adj. <span class=\"greek\">ἡ</span> <span class=\"greek\">Τρ</span>. <span class=\"greek\">χώρα</span> a região da Traconítide <span class=\"greek\">Φιλίππου</span> <span class=\"greek\">τετραρχοῦντος</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">Ἰτουραίας</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">Τραχωνίτιδος</span> <span class=\"greek\">χώρας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:1</a>.—GRindfleisch, Die Landschaft Haurān in röm. Zeit. u. in der Gegenwart: ZDPV 21, 1898, 1–46; Schürer I 337f; HGuthe, RE XX 7f; DSourdel, Les Cultes de Hauran à l’ époque Romaine ’52; Kl. Pauly I 839f; BHHW III 2017f.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0361-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τρεῖς, τρία</h1><div class=\"entry-meta\"><span>numeral cardinal</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τρεῖς</span>, <span class=\"greek\">τρία</span> gen. <span class=\"greek\">τριῶν</span>, dat. <span class=\"greek\">τρισίν</span> (Hom.+) três <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.40\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:40</a> (Jon 2:1); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 8:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.56\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:56</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.19\" target=\"_blank\" rel=\"noopener noreferrer\">J 2:19</a> al. <span class=\"greek\">τὰ</span> <span class=\"greek\">τρία</span> <span class=\"greek\">ταῦτα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.13.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 13:13</a> (cf. Philo, Det. Pot. Ins. 169 <span class=\"greek\">τὰ</span> <span class=\"greek\">ἑπτὰ</span> <span class=\"greek\">ταῦτα</span> e várias vezes <span class=\"greek\">τρία</span> <span class=\"greek\">ταῦτα</span>: Leg. All. 1, 93; 3, 249, Mos. 1, 224). <span class=\"greek\">τρεῖς</span> <span class=\"greek\">εἰσιν</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">μαρτυροῦντες</span> são três os que dão testemunho <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.5.7\" target=\"_blank\" rel=\"noopener noreferrer\">1J 5:7</a> (cf. Alexis, Fgm. 271 <span class=\"greek\">τρεῖς</span> <span class=\"greek\">δ</span>’ <span class=\"greek\">εἰσὶν</span> <span class=\"greek\">αἱ</span> <span class=\"greek\">κεκτημέναι</span>).—Sobre <span class=\"greek\">ἐν</span> <span class=\"greek\">τρισὶν</span> <span class=\"greek\">ἡμέραις</span> (<span class=\"greek\">ἐν</span> 10a) e <span class=\"greek\">μετὰ</span> <span class=\"greek\">τρεῖς</span> <span class=\"greek\">ἡμέρας</span> (<span class=\"greek\">μετά</span> B 2a) v. WBauer, D. Leben Jesu im Zeitalter d. ntl. Apokryphen 1909, 253f. Ambas as expressões juntas, evidentemente com o mesmo significado: Sb 7696, 120f [250 d.C.]; sobre <span class=\"greek\">μετὰ</span> <span class=\"greek\">τρ</span>. <span class=\"greek\">ἡμ</span>.=‘no terceiro dia’ v. Jos., Ant. 7, 280f; 8, 214 e 218.—Para <span class=\"greek\">δύο</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">τρεῖς</span> v. <span class=\"greek\">δύο</span> a<span class=\"greek\">α</span><span class=\"hebrew\">ג</span>.—V. s.v. <span class=\"greek\">πνεῦμα</span> 8 e v. FGöbel, Formen u. Formeln der epischen Dreiheit in d. griech. Dichtung ’35; FNötscher, Biblica 35, ’54, 313–19; JBauer, Biblica 39, ’58, 354–58; JJeremias, KGKuhn Festschr. ’71, 221–29; RAC IV 269–310; BHHW I 354f.—B. 941ff. DELG. M-M. EDNT. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0361-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Τρεῖς Ταβέρναι</h1><div class=\"entry-meta\"><span>nome próprio plural</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Τρεῖς</span> <span class=\"greek\">Ταβέρναι</span> v. <span class=\"greek\">ταβέρναι</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0361-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τρέμω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τρέμω</span> empregado somente no pres. e no imperf. (Hom.+; PFay 124, 27; PGM 12, 248f; IDefixWünsch 4, 44; LXX, pseudepígrafos, Philo, Joseph.; Just., D. 30, 3; Mel., P. 24, 168 al.), mas também em sentido fig. ter medo, temer, sentir reverência (Jos., Bell. 1, 341; 6, 395).</p><p class=\"entry-text\"><span class=\"sense-number\">①</span> agitar-se involuntariamente, tremer, estremecer (Mel., P. 98, 744f; <span class=\"greek\">τοῦ</span> <span class=\"greek\">λαοῦ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">τρέμοντος</span> <span class=\"greek\">ἔτρεμεν</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">γῆ</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.47\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:47</a>. Com <span class=\"greek\">φοβεῖσθαι</span> (Da 5:19 Theod.; JosAs 23:16; Philo, Leg. All. 3, 54) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:33</a>. Nessas passagens, o tremor físico é provavelmente o componente semântico primário, ao passo que nas seguintes há maior ênfase no aspecto psicológico.</p><p class=\"entry-text\"><span class=\"sense-number\">②</span> sentir intensamente o impacto de algo transcendente, tremer, sentir reverência. Com <span class=\"greek\">θαμβεῖν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:6</a> t.r. (leitura erasmiana). Com acus. tremer diante de, sentir reverência por (Trag. et al.; Herm. Wr. 1, 7; Just., D. 30, 3; Mel., P. 24, 168) <span class=\"greek\">τὰ</span> <span class=\"greek\">λόγια</span> 1 Cl 13:4 (Is 66:2). <span class=\"greek\">τοὺς</span> <span class=\"greek\">λόγους</span> B 19:4; D 3:8. <span class=\"greek\">δόξας</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">τρέμουσιν</span> <span class=\"greek\">βλασφημοῦντες</span> não temem blasfemar contra anjos gloriosos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:10</a> (B-D-F §415; Rob. 1121f).—DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0361-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τρέπω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τρέπω</span> 1 aor. <span class=\"greek\">ἔτρεψα</span> (Hom.+)</p><p class=\"entry-text\"><span class=\"sense-number\">①</span> voz ativa, fazer tender para determinado curso de ação, voltar, dirigir <span class=\"greek\">τινὰ</span> <span class=\"greek\">εἴς</span> <span class=\"greek\">τι</span> voltar ou inclinar alguém para alguma coisa MPol 2:4 (TestJob 20:1; Ath. 22:3).</p><p class=\"entry-text\"><span class=\"sense-number\">②</span> voz média: fut. <span class=\"greek\">τρέψομαι</span> (4 Macc 1:12; Tat. 3, 3); 1 aor. <span class=\"greek\">ἐτρεψάμην</span> LXX; 2 aor. <span class=\"greek\">ἐτραπόμην</span> (Ath. 6, 2); voz passiva: 2 aor. com valor médio <span class=\"greek\">ἐτράπην</span> LXX voltar-se para fazer algo, voltar-se (Jos., C. Ap. 1, 25) com indicação do ponto de partida e do objetivo (Socrat., Ep. 17, 2 [p. 264 Malherbe] <span class=\"greek\">οἱ</span> <span class=\"greek\">νέοι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ἀκρασίαν</span> <span class=\"greek\">ἐτρέποντο</span>; Appian, Bell. Civ. 2, 22 §83 <span class=\"greek\">ἐς</span> <span class=\"greek\">ἁρπαγὰς</span> <span class=\"greek\">ἐτράποντο</span>=voltaram-se para a pilhagem; escólio sobre Nicander, Ther. 825 <span class=\"greek\">εἰς</span> <span class=\"greek\">φυγὴν</span> <span class=\"greek\">τρεπόμενοι</span>; EpArist 245 <span class=\"greek\">τρέπεσθαι</span> <span class=\"greek\">εἰς</span>; igualmente Jos., Ant. 18, 87; Just., D. 91, 3 <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">εὐσέβειαν</span> <span class=\"greek\">ἐτράπησαν</span>) <span class=\"greek\">ἔνθεν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">βλασφημίαν</span> <span class=\"greek\">τρέπονται</span> passam disso (isto é, da admiração) à blasfêmia 2 Cl 13:3.—B. 666. DELG.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0361-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τρέφω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τρέφω</span> fut. <span class=\"greek\">θρέψω</span>; 1 aor. <span class=\"greek\">ἔθρεψα</span>. Voz passiva: aor. <span class=\"greek\">ἐτράφην</span> LXX; partic. <span class=\"greek\">τραφείς</span>; partic. perf. <span class=\"greek\">τεθραμμένος</span> (Hom.+).</p><p class=\"entry-text\"><span class=\"sense-number\">①</span> cuidar mediante o fornecimento de alimento ou nutrição, alimentar, nutrir, sustentar animais (X., Mem. 2, 9, 2; Is 7:21; PsSol 5:9) ou seres humanos (PsSol 5:11; TestJob 10:3; Ar. 7, 1) com acus.: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:26</a>; 25:37; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.24\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.12.6\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 12:6</a>, 14 (pass.); B 10:11. Ocasionalmente também a respeito de plantas (Il. 18, 57) <span class=\"greek\">ἡ</span> <span class=\"greek\">πτελέα</span> <span class=\"greek\">ὕδωρ</span> <span class=\"greek\">ἔχουσα</span> <span class=\"greek\">τρέφει</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἄμπελον</span> Hs 2:8.—A respeito dos seios maternos que amamentam ou nutrem (cf. Od. 12, 134; Hdt. 1, 136; PRyl 178, 5) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.29\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:29</a> (abs.). <span class=\"greek\">ἐθρέψατε</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">καρδίας</span> <span class=\"greek\">ὑμῶν</span> engordastes a vós mesmos com a vida de prazeres <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.5\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:5</a>. Em linguagem figurada a respeito de Paulo <span class=\"greek\">πόλλους</span> <span class=\"greek\">θρέψει</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">λόγῳ</span> AcPl Ha 7, 6. Em <span class=\"greek\">διὰ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">τρέφεσθαι</span> <span class=\"greek\">αὐτῶν</span> (isto é, os habitantes de Tiro e Sidom) <span class=\"greek\">τὴν</span> <span class=\"greek\">χώραν</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">βασιλικῆς</span>, <span class=\"greek\">τρέφεσθαι</span> pode estar tanto na voz média como na passiva, porque sua região se sustentava ou era sustentada (mediante a importação de cereais) a partir da região do rei <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 12:20</a> (X., An. 7, 4, 11 tem a voz média <span class=\"greek\">τρέφεσθαι</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">κωμῶν</span>).</p><p class=\"entry-text\"><span class=\"sense-number\">②</span> cuidar de crianças criando-as, criar, educar, instruir (Hom.+; 1 Macc 3:33; 11:39; Jos., Ant. 2, 209) <span class=\"greek\">τινά</span> alguém Hv 1, 1, 1. Voz passiva: crescer (Diod S 4, 81, 1; Aelian, VH 12, 1 p. 117, 2 H.; Jos., C. Ap. 1, 141; Just., A I, 57, 1) <span class=\"greek\">Ναζαρά</span>, <span class=\"greek\">οὗ</span> <span class=\"greek\">ἦν</span> <span class=\"greek\">τεθραμμένος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:16</a> (v. <span class=\"greek\">ἀνατρέφω</span> a). <span class=\"greek\">τραφέντα</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">Ναζαρά</span> AcPl Ha 8, 29.—CMoussy, Recherches sur <span class=\"greek\">τρέφω</span> et al., ’69. Schmidt, Syn. IV 98–105. DELG. M-M. Spicq. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0361-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τρέχω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τρέχω</span> imperf. <span class=\"greek\">ἔτρεχον</span>; fut. <span class=\"greek\">δραμοῦμαι</span> (LXX; TestJud 25:5); 2 aor. <span class=\"greek\">ἔδραμον</span> (Hom.+) ‘correr’</p><p class=\"entry-text\"><span class=\"sense-number\">①</span> realizar movimento linear rápido, correr, precipitar-se, avançar, lit. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.20.2\" target=\"_blank\" rel=\"noopener noreferrer\">J 20:2</a>, 4; GPt 3:6; GJs 4:4. <span class=\"greek\">δραμών</span> seguido de verbo finito (Gen 24:28; Jos., Bell. 6, 254; 294) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.48\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:48</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.36\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:36</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.20\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 15:20</a> (o movimento rápido do pai contraria a <span class=\"greek\">σεμνότης</span> que se esperaria de uma pessoa em sua posição). Seguido de inf. de finalidade <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.28.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 28:8</a>. O objetivo é indicado com <span class=\"greek\">ἐπί</span> e acus. (Alciphron 3, 17, 2; 3, 40, 3) <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">λῃστήν</span> avançar contra um salteador (para capturá-lo) MPol 7:1 (cf. Sus 38 Theod.; Test Jud 3:1); <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">μνημεῖον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:12</a> (cf. Gen 24:20). Com <span class=\"greek\">εἰς</span> (TestAbr A 3 p. 80, 3f [Stone p. 8] <span class=\"greek\">δραμών</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">φρέαρ</span>): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.28\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 19:28</a> D. <span class=\"greek\">τρ</span>. <span class=\"greek\">εἰς</span> <span class=\"greek\">πόλεμον</span> precipitar-se na batalha <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.9.9\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 9:9</a>. Com <span class=\"greek\">πρός</span> (ParJer 9:31): GJs 12:2. A respeito de corrida a pé em um estádio <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.24\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 9:24ab</a>.—No sentido de vir correndo GJs 8:3.</p><p class=\"entry-text\"><span class=\"sense-number\">②</span> fazer um esforço para avançar espiritual ou intelectualmente, esforçar-se, extensão fig. de 1: tomando por base as corridas a pé no estádio (sobre o emprego de tais figuras na diatribe cínico-estoica, v. PWendland, Die urchristl. Literaturformen: Hdb. I 3, 1912 p. 357, 4), esforçar-se até o limite de suas forças na tentativa de progredir, empenhar-se em avançar <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:16</a> (a ênfase recai inteiramente sobre o esforço que a pessoa faz; cf. Anth. Pal. 11, 56 Düb. <span class=\"greek\">μὴ</span> <span class=\"greek\">τρέχε</span>, <span class=\"greek\">μὴ</span> <span class=\"greek\">κοπία</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.24\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 9:24c</a>, 26. <span class=\"greek\">μήπως</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">κενὸν</span> <span class=\"greek\">τρέχω</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">ἔδραμον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 2:2</a> (<span class=\"greek\">πώς</span> 2c). Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:16</a>=Pol 9:2. Sobre <span class=\"greek\">τρ</span>. <span class=\"greek\">τὸν</span> <span class=\"greek\">ἀγῶνα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.1\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:1</a> v. <span class=\"greek\">ἀγών</span> 1. <span class=\"greek\">ἐτρέχετε</span> <span class=\"greek\">καλῶς</span> estáveis progredindo tão bem <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.7\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 5:7</a> (cf. Philo, Leg. All. 3, 48 <span class=\"greek\">καλὸν</span> <span class=\"greek\">δρόμον</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἄριστον</span> <span class=\"greek\">ἀγώνισμα</span>; OdeSol 11:3 <span class=\"greek\">ἔδραμον</span> <span class=\"greek\">ὁδὸν</span> <span class=\"greek\">ἀληθείας</span>).—VPfitzner, Paul and the Agon Motif ’67; HFunke, Antisthenes bei Paulus: Her 98, ’70, 459–71.</p><p class=\"entry-text\"><span class=\"sense-number\">③</span> prosseguir rapidamente e sem impedimento, progredir, extensão fig. de 1 <span class=\"greek\">ἵνα</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">λόγος</span> <span class=\"greek\">τ</span>. <span class=\"greek\">κυρίου</span> <span class=\"greek\">τρέχῃ</span> para que a palavra do Senhor avance rapidamente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 3:1</a> (cf. Ps 147:4).—JDerrett, Biblica 66, ’85, 560–67.—B. 692. DELG. M-M. TW.</p></section></article>"};
